import{R as e,e as a,f as o,U as n}from"./chunks/framework.ywem4qy5.js";const g=JSON.parse('{"title":"Captcha.eu","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/captchas/captcha-eu.md","filePath":"integrations/captchas/captcha-eu.md","lastUpdated":1778045915000}'),r={name:"integrations/captchas/captcha-eu.md"};function s(i,t,c,h,l,p){return a(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="captcha-eu" tabindex="-1">Captcha.eu <a class="header-anchor" href="#captcha-eu" aria-label="Permalink to &quot;Captcha.eu&quot;">​</a></h1><p>Follow the below steps to connect Formie to Captcha.eu.</p><h3 id="step-1-open-the-captcha-settings" tabindex="-1">Step 1. Open the Captcha Settings <a class="header-anchor" href="#step-1-open-the-captcha-settings" aria-label="Permalink to &quot;Step 1. Open the Captcha Settings&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Captchas</strong>.</li><li>Select <strong>Captcha.eu</strong> in the left-hand sidebar.</li><li>Turn on <strong>Enabled</strong>.</li></ol><h3 id="step-2-get-your-captcha-eu-keys" tabindex="-1">Step 2. Get your Captcha.eu Keys <a class="header-anchor" href="#step-2-get-your-captcha-eu-keys" aria-label="Permalink to &quot;Step 2. Get your Captcha.eu Keys&quot;">​</a></h3><ol><li>Go to <a href="https://www.captcha.eu/" target="_blank" rel="noreferrer">Captcha.eu</a> and create an account, or sign in to an existing one.</li><li>In the dashboard, go to <strong>Domains</strong> and add the domain you want to protect.</li><li>Captcha.eu will generate a <strong>Public Key</strong> and <strong>Rest Key</strong> for that domain.</li><li>Copy both keys.</li></ol><h3 id="step-3-connect-formie-to-captcha-eu" tabindex="-1">Step 3. Connect Formie to Captcha.eu <a class="header-anchor" href="#step-3-connect-formie-to-captcha-eu" aria-label="Permalink to &quot;Step 3. Connect Formie to Captcha.eu&quot;">​</a></h3><ol><li>Paste the <strong>Public Key</strong> into the <strong>Public Key</strong> field in Formie.</li><li>Paste the <strong>Rest Key</strong> into the <strong>Rest Key</strong> field in Formie.</li><li>Leave <strong>Endpoint</strong> as <code>https://www.captcha.eu</code> unless Captcha.eu has given you a different endpoint.</li><li>Save the captcha settings.</li></ol><h3 id="step-4-form-setting" tabindex="-1">Step 4. Form Setting <a class="header-anchor" href="#step-4-form-setting" aria-label="Permalink to &quot;Step 4. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to protect.</li><li>Enable <strong>Captcha.eu</strong> for that form.</li><li>For multi-page forms, turn on <strong>Show on All Pages</strong> if the captcha should run on every page instead of only the final submit step.</li><li>Save the form.</li></ol><p>Captcha.eu relies on Formie&#39;s front-end output, so test it on the rendered form after saving your settings.</p>',11)])])}const d=e(r,[["render",s]]);export{g as __pageData,d as default};
